# [doc = " Messages sent from the server to the client over the client protocol socket."] # [doc = ""] # [doc = " Variant order is frozen for endpoint generation 1. Add compatible endpoint"] # [doc = " behavior through `EndpointControl`, and ignore unrecognized named controls."] # [derive (Debug , Clone , PartialEq , Eq , Serialize , Deserialize)] pub enum ServerMessage { # [doc = " Handshake response: server acknowledges (or rejects) the client."] Welcome { # [doc = " Protocol version the server speaks."] version : u32 , # [doc = " Render encoding selected by the server for this connection."] encoding : RenderEncoding , # [doc = " If present, the handshake failed and this describes why."] # [doc = " The client should exit with a clear error message."] error : Option < String > , } , # [doc = " Terminal bytes to write directly for a terminal-ANSI client."] Terminal (TerminalFrame) , # [doc = " Client-local Kitty graphics bytes to write directly to the host terminal."] Graphics { # [doc = " Raw Kitty graphics protocol bytes."] bytes : Vec < u8 > , } , # [doc = " Server is shutting down. Clients should exit gracefully."] ServerShutdown { # [doc = " Optional reason for the shutdown."] reason : Option < String > , } , # [doc = " A notification event (sound/toast) to be rendered locally by the client."] Notify { # [doc = " What kind of notification."] kind : NotifyKind , # [doc = " Human-readable title or sound label."] message : String , # [doc = " Optional human-readable notification body."] body : Option < String > , } , # [doc = " OSC 52 clipboard data forwarded from a PTY through the server."] Clipboard { # [doc = " Base64-encoded clipboard data."] data : String , } , # [doc = " Set the foreground client's outer terminal window title."] WindowTitle { # [doc = " Sanitized title to write with OSC 0. `None` restores Herdr's default title."] title : Option < String > , } , # [doc = " Client-local runtime config changed on disk; refresh it without reconnecting."] ReloadSoundConfig , # [doc = " Whether the client should currently capture host mouse input."] MouseCapture { # [doc = " True when Herdr mouse UI is enabled or the focused pane app requests mouse reporting."] enabled : bool , # [doc = " True only while the focused pane requests DEC SGR pixel mode 1016."] sgr_pixels : bool , } , # [doc = " Ring the foreground client's outer terminal for pane-originated BEL characters."] TerminalBell { # [doc = " Number of BEL characters parsed from one PTY read."] count : u16 , } , # [doc = " One validated Herdr-owned Kitty regular-file RGBA transmission."] GraphicsFile { path : String , expected_len : u64 , image_id : u32 , transfer_id : u64 , leading : Vec < u8 > , control : String , # [doc = " ClientShell upload identity. `None` targets a direct terminal client."] surface_asset : Option < SurfaceGraphicsAssetKey > , } , # [doc = " Suppress a direct command that expired before terminal delivery."] GraphicsTransmissionRetired { transfer_id : u64 , image_id : u32 } , # [doc = " Initial metadata for a client-owned shell."] ClientShellSnapshot (Box < ClientShellSnapshot >) , # [doc = " Active-tab pane content rendered at a client-requested origin-relative size."] PaneSurface (PaneSurfaceFrame) , # [doc = " Ephemeral semantic notification delivered over the private control lane."] # [doc = " It is sent only to currently connected client-rendered shells."] SemanticNotification (SemanticNotification) , # [doc = " Immediate endpoint error that the client-rendered shell must show regardless of notification policy."] ClientShellError { message : String } , # [doc = " Exact Kitty keyboard flags requested by a directly attached terminal."] # [doc = " Zero restores the host terminal's previous keyboard mode."] DirectTerminalKeyboardProtocol { flags : u16 , modify_other_keys_level : u8 , } , # [doc = " Whether the focused pane or popup needs the shell host to report every key."] ClientShellKeyboardReportAll { enabled : bool } , # [doc = " One ordered chunk of the final response to an endpoint operation."] ClientShellEndpointResponseChunk { boot_id : String , request_id : String , final_chunk : bool , data : Vec < u8 > , } , # [doc = " Incremental terminal-cell update for a previously committed pane surface."] PaneSurfacePatch (PaneSurfacePatch) , # [doc = " Extensible named control message for the stable client-owned endpoint protocol."] # [doc = ""] # [doc = " This variant is append-only. Its bincode tag and two-string payload are part"] # [doc = " of endpoint generation 1 and must not change."] EndpointControl { kind : String , data : String } , }
# [doc = " Errors that can occur during framing operations."] # [derive (Debug)] pub enum FramingError { # [doc = " The decoded payload length exceeds the configured maximum frame size."] Oversized { claimed : usize , max : usize } , # [doc = " An I/O error occurred while reading or writing."] Io (io :: Error) , # [doc = " Bincode serialization or deserialization failed."] Bincode (String) , # [doc = " The connection was closed before a complete frame could be read."] UnexpectedEof , }
impl std :: fmt :: Display for FramingError { fn fmt (& self , f : & mut std :: fmt :: Formatter < '_ >) -> std :: fmt :: Result { match self { FramingError :: Oversized { claimed , max } => { write ! (f , "frame size {claimed} exceeds maximum {max}") } FramingError :: Io (e) => write ! (f , "I/O error: {e}") , FramingError :: Bincode (e) => write ! (f , "bincode error: {e}") , FramingError :: UnexpectedEof => write ! (f , "unexpected end of stream") , } } }
impl std :: error :: Error for FramingError { fn source (& self) -> Option < & (dyn std :: error :: Error + 'static) > { match self { FramingError :: Io (e) => Some (e) , _ => None , } } }
impl From < io :: Error > for FramingError { fn from (e : io :: Error) -> Self { FramingError :: Io (e) } }
# [doc = " Serializes a message and writes it as a length-prefixed frame:"] # [doc = " `[u32LE length][bincode payload]`."] # [doc = ""] # [doc = " This is a blocking/synchronous write suitable for use with `std::os::unix::net::UnixStream`"] # [doc = " in blocking mode, or with any `Write` implementor."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Returns `FramingError::Bincode` if the payload length exceeds `u32::MAX`"] # [doc = " (would be truncated by the length prefix cast)."] pub fn write_message < W : Write , M : Serialize > (writer : & mut W , msg : & M) -> Result < () , FramingError > { let payload = bincode :: serde :: encode_to_vec (msg , bincode :: config :: standard ()) . map_err (| e | FramingError :: Bincode (e . to_string ())) ? ; let len = payload . len () ; if len > u32 :: MAX as usize { return Err (FramingError :: Bincode (format ! ("payload length {len} exceeds u32::MAX ({}), would be truncated by length prefix" , u32 :: MAX))) ; } writer . write_all (& (len as u32) . to_le_bytes ()) ? ; writer . write_all (& payload) ? ; writer . flush () ? ; Ok (()) }
# [doc = " Reads and deserializes a length-prefixed frame from a reader."] # [doc = ""] # [doc = " Reassembles partial reads correctly. Rejects frames whose declared"] # [doc = " length exceeds `max_frame_size` without panicking or allocating"] # [doc = " oversized buffers."] pub fn read_message < R : Read , M : for < 'de > Deserialize < 'de > > (reader : & mut R , max_frame_size : usize ,) -> Result < M , FramingError > { let mut len_buf = [0u8 ; LENGTH_PREFIX_BYTES] ; read_exact_or_eof (reader , & mut len_buf) ? ; let claimed_len = u32 :: from_le_bytes (len_buf) as usize ; if claimed_len > max_frame_size { return Err (FramingError :: Oversized { claimed : claimed_len , max : max_frame_size , }) ; } let mut payload = vec ! [0u8 ; claimed_len] ; read_exact_or_eof (reader , & mut payload) ? ; let (msg , consumed) = bincode :: serde :: decode_from_slice (& payload , bincode :: config :: standard ()) . map_err (| e | FramingError :: Bincode (e . to_string ())) ? ; if consumed != claimed_len { return Err (FramingError :: Bincode (format ! ("decoded {} bytes but payload length was {claimed_len}; trailing bytes are not allowed" , consumed))) ; } Ok (msg) }
# [doc = " Like `Read::read_exact`, but returns `FramingError::UnexpectedEof`"] # [doc = " when the reader hits end-of-stream before filling the buffer, instead"] # [doc = " of the generic `io::ErrorKind::UnexpectedEof`."] fn read_exact_or_eof < R : Read > (reader : & mut R , buf : & mut [u8]) -> Result < () , FramingError > { reader . read_exact (buf) . map_err (| e | { if e . kind () == io :: ErrorKind :: UnexpectedEof { FramingError :: UnexpectedEof } else { FramingError :: Io (e) } }) }
# [doc = " Result of checking a client's protocol version against the server's."] # [derive (Debug , Clone , PartialEq , Eq)] pub enum VersionCheck { # [doc = " Versions are compatible. The server should reply with a successful Welcome."] Compatible , # [doc = " Versions are incompatible. The server should reply with a Welcome error and close."] Incompatible (String) , }
